# owner: platform
"""Tests for the uncovered stretches inside opening hours."""

import unittest
from hourglass.models import Span
from hourglass.gaps import gap_labels

class GapLabelTests(unittest.TestCase):
    def test_gap_between_two_shifts(self):
        worked = [Span(780, 1020), Span(540, 720)]
        labels = gap_labels(worked, Span(540, 1020))
        self.assertEqual(labels, ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_edges(self):
        labels = gap_labels([Span(600, 960)], Span(540, 1020))
        self.assertEqual(
            labels, ["gap 09:00-10:00 (60 min)", "gap 16:00-17:00 (60 min)"]
        )

    def test_overlapping_and_touching_spans_leave_no_gap(self):
        worked = [Span(540, 660), Span(600, 720), Span(720, 780)]
        self.assertEqual(gap_labels(worked, Span(540, 780)), [])

    def test_fully_covered_opening_hours(self):
        self.assertEqual(gap_labels([Span(540, 1020)], Span(540, 1020)), [])

    def test_nobody_working(self):
        self.assertEqual(gap_labels([], Span(540, 1020)), ["gap 09:00-17:00 (480 min)"])

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            gap_labels([Span(480, 600)], Span(540, 1020))

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            gap_labels([Span(1000, 1080)], Span(540, 1020))
